  if (password.length < 8) list.push("short");
  let hasDigit = false;
  for (const ch of password) {
    if (ch >= "0" && ch <= "9") hasDigit = true;
  }
  if (!hasDigit) list.push("no digit");
  return list.length === 0 ? "OK" : list.join("+");
}

