function incomeTax(income) {
  let tax = 0;
  if (income > 800000) tax = tax + 0.15 * Math.min(income - 800000, 2200000);
  if (income > 3000000) tax = tax + 0.2 * (income - 3000000);
  return Math.round(tax);
}

console.log(incomeTax(800000), incomeTax(1800000), incomeTax(5000000));

function discountedPrice(price, percent) {
  if (percent < 0 || percent > 100) return "invalid";
  const discount = Math.round((price * percent) / 100);
  return price - discount;
}

console.log(discountedPrice(999, 15), discountedPrice(1000, 0), discountedPrice(1000, 110));

