function notesFor(amount) {
  const thousands = Math.floor(amount / 1000);
  const fiveHundreds = (amount % 1000) / 500;
  return `${thousands}/${fiveHundreds}`;
}

console.log(notesFor(3500), notesFor(500), notesFor(4000));

