function usernameProblems(name) {
  const problems = [];
  if (name.length < 3) problems.push("too short");
  if (name.length > 15) problems.push("too long");
  let hasSpace = false;
  for (const ch of name) {
    if (ch === " ") hasSpace = true;
  }
  if (hasSpace) problems.push("has a space");
  return problems;
}

function report(name) {
  const problems = usernameProblems(name);
  return problems.length === 0 ? "OK" : problems.join(", ");
}

